using Microsoft.Extensions.AI;
using Moq;
using Xunit;
using FluentAssertions;

public class SupportTicketTriageServiceTests
{
    [Fact]
    public async Task TriageTicketAsync_ValidUrgentPrompt_ParsesCategoryAndUrgencyCorrectly()
    {
        // Arrange: Mock IChatClient to return a canned completion
        var mockChatClient = new Mock<IChatClient>();
        var cannedResponse = new ChatCompletion(new ChatMessage(ChatRole.Assistant, "Billing|5"))
        {
            Usage = new AdditionalPropertiesDictionary
            {
                ["TotalTokens"] = 45
            }
        };

        mockChatClient
            .Setup(c => c.CompleteAsync(
                It.IsAny<IList<ChatMessage>>(),
                It.IsAny<ChatOptions>(),
                It.IsAny<CancellationToken>()))
            .ReturnsAsync(cannedResponse);

        var triageService = new SupportTicketTriageService(mockChatClient.Object);

        // Act
        var result = await triageService.TriageAsync("My credit card was double-charged $49.00!");

        // Assert
        result.Category.Should().Be("Billing");
        result.Urgency.Should().Be(5);

        // Verify prompt structure sent to model
        mockChatClient.Verify(c => c.CompleteAsync(
            It.Is<IList<ChatMessage>>(msgs => 
                msgs.Any(m => m.Role == ChatRole.System && m.Text.Contains("triage classifier")) &&
                msgs.Any(m => m.Role == ChatRole.User && m.Text.Contains("double-charged"))),
            It.IsAny<ChatOptions>(),
            It.IsAny<CancellationToken>()), Times.Once);
    }
}
